package v1alpha1

import (
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
)

// Well-known labels applied to every object generated by the platform operators.
const (
	LabelTenant      = "platform.mycompany.io/tenant"
	LabelEnvironment = "platform.mycompany.io/environment"
	LabelManagedBy   = "platform.mycompany.io/managed-by"

	// ManagedByValue is the value of LabelManagedBy for objects owned by this operator.
	ManagedByValue = "environment-operator"

	// OwnerUIDAnnotation records the UID of the Environment that owns a generated
	// object. Namespaces and child objects cannot carry a controller reference to
	// a namespaced Environment (cross-namespace owner references are invalid and
	// cluster-scoped dependents cannot have namespaced owners), so ownership is
	// recorded here and verified before every adoption and delete.
	OwnerUIDAnnotation = "platform.mycompany.io/owner-uid"

	// EnvironmentFinalizer guards deletion of the generated namespace.
	EnvironmentFinalizer = "platform.mycompany.io/environment-cleanup"
)

// Condition types reported on Environment.status.conditions.
const (
	ConditionReady          = "Ready"
	ConditionNamespaceReady = "NamespaceReady"
	ConditionTemplatesReady = "TemplatesReady"
	ConditionExpired        = "Expired"
	ConditionTenantVerified = "TenantVerified"
)

// Phase values for Environment.status.phase.
const (
	PhasePending     = "Pending"
	PhaseReady       = "Ready"
	PhaseFailed      = "Failed"
	PhaseExpired     = "Expired"
	PhaseTerminating = "Terminating"
)

// EnvironmentType is the kind of environment; it selects the baseline template set.
// +kubebuilder:validation:Enum=dev;staging;prod;preview
type EnvironmentType string

const (
	EnvironmentTypeDev     EnvironmentType = "dev"
	EnvironmentTypeStaging EnvironmentType = "staging"
	EnvironmentTypeProd    EnvironmentType = "prod"
	EnvironmentTypePreview EnvironmentType = "preview"
)

// EnvironmentSpec defines the desired state of an Environment.
type EnvironmentSpec struct {
	// Tenant is the name of the owning Tenant. The generated namespace is named
	// "<tenant>-<name>".
	// +kubebuilder:validation:MinLength=1
	// +kubebuilder:validation:MaxLength=63
	// +kubebuilder:validation:Pattern=`^[a-z0-9]([-a-z0-9]*[a-z0-9])?$`
	Tenant string `json:"tenant"`

	// Type selects the baseline quota, network policy and configmap set.
	// +kubebuilder:default=dev
	Type EnvironmentType `json:"type"`

	// TTL, when set, deletes the Environment (and its namespace) this long after creation.
	// +optional
	TTL *metav1.Duration `json:"ttl,omitempty"`

	// Template names the template set under templates/ used to render the
	// baseline objects. Only "baseline" is embedded.
	// +optional
	// +kubebuilder:default=baseline
	Template string `json:"template,omitempty"`

	// Cluster is the cluster this Environment is meant for. When set and the
	// operator was started with --cluster-name, only a matching operator reconciles it.
	// +optional
	Cluster string `json:"cluster,omitempty"`
}

// EnvironmentStatus defines the observed state of an Environment.
type EnvironmentStatus struct {
	// Phase is one of Pending, Ready, Failed, Expired or Terminating.
	// +optional
	Phase string `json:"phase,omitempty"`

	// Namespace is the generated namespace, "<tenant>-<name>".
	// +optional
	Namespace string `json:"namespace,omitempty"`

	// URL is where the environment is served, e.g. https://<name>.<tenant>.<base-domain>.
	// +optional
	URL string `json:"url,omitempty"`

	// ExpiresAt is set when spec.ttl is set: creationTimestamp + ttl.
	// +optional
	ExpiresAt *metav1.Time `json:"expiresAt,omitempty"`

	// ObservedGeneration is the .metadata.generation last reconciled.
	// +optional
	ObservedGeneration int64 `json:"observedGeneration,omitempty"`

	// Conditions follow the Kubernetes condition conventions.
	// +optional
	// +listType=map
	// +listMapKey=type
	Conditions []metav1.Condition `json:"conditions,omitempty"`
}

// +kubebuilder:object:root=true
// +kubebuilder:subresource:status
// +kubebuilder:resource:scope=Namespaced,shortName=env
// +kubebuilder:printcolumn:name="Tenant",type=string,JSONPath=`.spec.tenant`
// +kubebuilder:printcolumn:name="Type",type=string,JSONPath=`.spec.type`
// +kubebuilder:printcolumn:name="Phase",type=string,JSONPath=`.status.phase`
// +kubebuilder:printcolumn:name="URL",type=string,JSONPath=`.status.url`
// +kubebuilder:printcolumn:name="Expires",type=date,JSONPath=`.status.expiresAt`
// +kubebuilder:printcolumn:name="Age",type=date,JSONPath=`.metadata.creationTimestamp`

// Environment is a short-lived or long-lived deployment target for a tenant.
type Environment struct {
	metav1.TypeMeta   `json:",inline"`
	metav1.ObjectMeta `json:"metadata,omitempty"`

	Spec   EnvironmentSpec   `json:"spec,omitempty"`
	Status EnvironmentStatus `json:"status,omitempty"`
}

// +kubebuilder:object:root=true

// EnvironmentList contains a list of Environment.
type EnvironmentList struct {
	metav1.TypeMeta `json:",inline"`
	metav1.ListMeta `json:"metadata,omitempty"`
	Items           []Environment `json:"items"`
}

func init() {
	SchemeBuilder.Register(&Environment{}, &EnvironmentList{})
}
